import { NextResponse } from "next/server";
import { prisma } from "@/lib/prisma";
import bcrypt from "bcryptjs";
import { signToken } from "@/lib/auth";

/**
 * POST /api/auth/login
 * เข้าสู่ระบบ — รองรับทั้ง Athlete (studentId) และ Club (email ประธานชมรม)
 *
 * Body: { username: string (studentId หรือ email), password: string }
 * Returns: { user/club, role } + set cookie "token" (httpOnly JWT)
 */
export async function POST(request: Request) {
  try {
    const body = await request.json();
    const username = body.username.trim().toLowerCase();
    const { password } = body;

    if (!username || !password) {
      return NextResponse.json(
        { error: "กรุณากรอก username และรหัสผ่าน" },
        { status: 400 }
      );
    }

    // ─── ลองค้นหาใน User table ก่อน (Athlete/Staff/Admin) ───
    const isEmail = username.includes("@");
    const studentId = isEmail ? username.replace("@up.ac.th", "") : username;

    const user = await prisma.user.findUnique({
      where: { studentId },
      include: { profile: true },
    });

    if (user) {
      // --- Verify password ---
      const isValid = await bcrypt.compare(password, user.password);
      if (!isValid) {
        return NextResponse.json(
          { error: "อีเมลหรือรหัสผ่านไม่ถูกต้อง" },
          { status: 401 }
        );
      }

      // Sign JWT
      const token = signToken({
        id: user.id,
        role: user.role,
        studentId: user.studentId,
      });

      const { password: _, ...safeUser } = user;

      const response = NextResponse.json({
        message: "เข้าสู่ระบบสำเร็จ",
        user: safeUser,
        role: user.role.toLowerCase(),
      });

      // Set httpOnly JWT cookie
      response.cookies.set("token", token, {
        path: "/",
        httpOnly: true,
        maxAge: 60 * 60 * 24, // 24h
        sameSite: "lax",
      });

      // Set role cookie (readable by JS) สำหรับ middleware
      response.cookies.set("role", user.role.toLowerCase(), {
        path: "/",
        httpOnly: false,
        maxAge: 60 * 60 * 24,
      });

      return response;
    }

    // ─── ลองค้นหาใน Club table (ประธานชมรม login ด้วย email) ───
    if (isEmail || username.includes("@")) {
      const club = await prisma.club.findUnique({
        where: { email: username },
      });

      if (club) {
        const isValid = await bcrypt.compare(password, club.password);
        if (!isValid) {
          return NextResponse.json(
            { error: "อีเมลหรือรหัสผ่านไม่ถูกต้อง" },
            { status: 401 }
          );
        }

        // Sign JWT for Club
        const token = signToken({
          id: club.id,
          role: "CLUB",
          clubId: club.id,
        });

        const { password: _, ...safeClub } = club;

        const response = NextResponse.json({
          message: "เข้าสู่ระบบสำเร็จ",
          club: safeClub,
          role: "club",
        });

        response.cookies.set("token", token, {
          path: "/",
          httpOnly: true,
          maxAge: 60 * 60 * 24,
          sameSite: "lax",
        });

        response.cookies.set("role", "club", {
          path: "/",
          httpOnly: false,
          maxAge: 60 * 60 * 24,
        });

        return response;
      }
    }

    return NextResponse.json(
      { error: "ไม่พบบัญชีผู้ใช้" },
      { status: 401 }
    );
  } catch (error) {
    console.error("[POST /api/auth/login]", error);
    return NextResponse.json(
      { error: "เกิดข้อผิดพลาดภายในระบบ" },
      { status: 500 }
    );
  }
}

import { NextResponse } from "next/server";
import { NextRequest } from "next/server";
import { prisma } from "@/lib/prisma";
import { getSession } from "@/lib/auth";

/**
 * GET /api/auth/me
 * ดูข้อมูล user ที่ login อยู่ปัจจุบัน
 * อ่าน JWT จาก httpOnly cookie "token"
 *
 * Returns: { id, role, user/club, profile? }
 */
export async function GET(request: NextRequest) {
  try {
    const session = getSession(request);

    if (!session) {
      return NextResponse.json(
        { error: "ไม่ได้เข้าสู่ระบบ" },
        { status: 401 }
      );
    }

    // ─── Club ───
    if (session.role === "CLUB" && session.clubId) {
      const club = await prisma.club.findUnique({
        where: { id: session.clubId },
        select: {
          id: true,
          name: true,
          sport: true,
          email: true,
          isActive: true,
          createdAt: true,
        },
      });

      if (!club) {
        return NextResponse.json({ error: "ไม่พบข้อมูลชมรม" }, { status: 404 });
      }

      return NextResponse.json({
        id: session.id,
        role: "club",
        club,
      });
    }

    // ─── User (Athlete / Staff / Admin) ───
    const user = await prisma.user.findUnique({
      where: { id: session.id },
      include: { profile: true },
    });

    if (!user) {
      return NextResponse.json({ error: "ไม่พบบัญชีผู้ใช้" }, { status: 404 });
    }

    const { password: _, ...safeUser } = user;

    return NextResponse.json({
      id: session.id,
      role: user.role.toLowerCase(),
      user: safeUser,
    });
  } catch (error) {
    console.error("[GET /api/auth/me]", error);
    return NextResponse.json(
      { error: "เกิดข้อผิดพลาดภายในระบบ" },
      { status: 500 }
    );
  }
}

import { NextResponse } from "next/server";
import { prisma } from "@/lib/prisma";
import bcrypt from "bcryptjs";

/**
 * POST /api/auth/register
 * สมัครบัญชีนักกีฬา + สร้าง profile
 *
 * Body: {
 *   studentId: string,
 *   password: string,
 *   profile: {
 *     firstName, lastName, faculty, major, studentLevel,
 *     year, nationalId, nationality, birthDate,
 *     gpaSemester?, gpaCumulative?,
 *     addressNo, subDistrict, district, province, postalCode, phone,
 *     photoUrl?
 *   }
 * }
 */
export async function POST(request: Request) {
  try {
    const body = await request.json();
    const { studentId, password, profile } = body;

    // --- Validation ---
    if (!studentId || !password) {
      return NextResponse.json(
        { error: "กรุณากรอกรหัสนิสิตและรหัสผ่าน" },
        { status: 400 }
      );
    }

    if (!/^\d{8}$/.test(studentId)) {
      return NextResponse.json(
        { error: "รหัสนิสิตต้องเป็นตัวเลข 8 หลัก" },
        { status: 400 }
      );
    }

    // --- Check duplicate ---
    const existing = await prisma.user.findUnique({
      where: { studentId },
    });

    if (existing) {
      return NextResponse.json(
        { error: "รหัสนิสิตนี้ลงทะเบียนแล้ว" },
        { status: 409 }
      );
    }

    // --- Hash password ---
    const hashedPassword = await bcrypt.hash(password, 10);

    // --- Create user + profile ---
    const email = `${studentId}@up.ac.th`;

    const user = await prisma.user.create({
      data: {
        studentId,
        email,
        password: hashedPassword,
        role: "ATHLETE",
        ...(profile
          ? {
              profile: {
                create: {
                  firstName: profile.firstName,
                  lastName: profile.lastName,
                  faculty: profile.faculty,
                  major: profile.major,
                  studentLevel: profile.studentLevel === "graduate" ? "GRADUATE" : "BACHELOR",
                  year: profile.year,
                  nationalId: profile.nationalId,
                  nationality: profile.nationality || "ไทย",
                  birthDate: new Date(profile.birthDate),
                  gpaSemester: profile.gpaSemester || null,
                  gpaCumulative: profile.gpaCumulative || null,
                  addressNo: profile.addressNo,
                  subDistrict: profile.subDistrict,
                  district: profile.district,
                  province: profile.province,
                  postalCode: profile.postalCode,
                  phone: profile.phone,
                  photoUrl: profile.photoUrl || null,
                },
              },
            }
          : {}),
      },
      include: { profile: true },
    });

    // Remove password from response
    const { password: _, ...safeUser } = user;

    return NextResponse.json(
      { message: "ลงทะเบียนสำเร็จ", user: safeUser },
      { status: 201 }
    );
  } catch (error) {
    console.error("[POST /api/auth/register]", error);
    return NextResponse.json(
      { error: "เกิดข้อผิดพลาดภายในระบบ" },
      { status: 500 }
    );
  }
}

import { NextResponse } from "next/server";
import type { NextRequest } from "next/server";
import { prisma } from "@/lib/prisma";
import { getSession } from "@/lib/auth";
import bcrypt from "bcryptjs";

type RouteParams = { params: Promise<{ id: string }> };

/**
 * PUT /api/clubs/[id]
 * อัปเดตข้อมูลชมรม (Admin หรือ Club ตัวเอง)
 * Body: { name, sport, email, password?, isActive? }
 */
export async function PUT(request: Request, { params }: RouteParams) {
  try {
    const session = getSession(request as NextRequest);
    const { id } = await params;

    // ตรวจสอบสิทธิ์ว่าต้องเป็น ADMIN หรือเป็น Club ตัวเอง
    if (!session || (session.role !== "ADMIN" && session.clubId !== id)) {
      return NextResponse.json(
        { error: "ไม่มีสิทธิ์เข้าถึง" },
        { status: 403 }
      );
    }

    const body = await request.json();
    const { name, sport, email, password, isActive } = body;

    const updateData: any = {};
    if (name) updateData.name = name;
    if (sport) updateData.sport = sport;
    if (email) updateData.email = email;
    if (isActive !== undefined && session.role === "ADMIN") {
        updateData.isActive = isActive;
    }

    if (password) {
      updateData.password = await bcrypt.hash(password, 10);
    }

    const club = await prisma.club.update({
      where: { id },
      data: updateData,
      select: {
        id: true,
        name: true,
        sport: true,
        email: true,
        isActive: true,
      }
    });

    return NextResponse.json({
      message: "อัปเดตข้อมูลชมรมสำเร็จ",
      club,
    });
  } catch (error) {
    console.error("[PUT /api/clubs/[id]]", error);
    return NextResponse.json(
      { error: "เกิดข้อผิดพลาดในการอัปเดตข้อมูลชมรม" },
      { status: 500 }
    );
  }
}

/**
 * DELETE /api/clubs/[id]
 * ปิดการใช้งานชมรม (Soft delete - isActive = false) สำหรับ Admin
 */
export async function DELETE(request: Request, { params }: RouteParams) {
  try {
    const session = getSession(request as NextRequest);

    // ตรวจสอบสิทธิ์ว่าต้องเป็น ADMIN เท่านั้น
    if (!session || session.role !== "ADMIN") {
      return NextResponse.json(
        { error: "ไม่มีสิทธิ์เข้าถึง (สำหรับผู้ดูแลระบบเท่านั้น)" },
        { status: 403 }
      );
    }

    const { id } = await params;

    const club = await prisma.club.update({
      where: { id },
      data: { isActive: false },
      select: {
        id: true,
        name: true,
        isActive: true,
      }
    });

    return NextResponse.json({
      message: "ปิดการใช้งานชมรมสำเร็จ",
      club,
    });
  } catch (error) {
    console.error("[DELETE /api/clubs/[id]]", error);
    return NextResponse.json(
      { error: "เกิดข้อผิดพลาดในการปิดการใช้งานชมรม" },
      { status: 500 }
    );
  }
}

