                          className="text-slate-400 hover:text-rose-700 text-xs p-1"
                          title="ลบรายงาน"
                        >
                          ลบ
                        </button>
                      </div>

                      <div className="grid grid-cols-3 gap-2 mt-4 pt-3 border-t border-slate-100 text-center text-xs">
