  "เปตอง", "เซปักตะกร้อ", "อีสปอร์ต", "แบดมินตัน", "เทนนิส", "ฟุตซอล", "เปตอง"
];

type Quota = {
  sport: string;
  maxStarters: string;
  maxSubstitutes: string;
  ageLimit: string;
};

export default function StaffCompetitionsPage() {
