      alert("กรุณากรอกชื่อและปี");
      return;
    }

    try {
      const res = await fetch("/api/competitions", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          ...form,
          quotas: quotas.filter((q) => q.sport)
        }),
      });

      if (!res.ok) {
        const data = await res.json();
        alert(data.error);
        return;
