"use client";

import { useState, useEffect, useCallback } from "react";
import { useRouter } from "next/navigation";
import LogoutButton from "@/components/shared/LogoutButton";

type SpecialRequest = {
  id: string;
  clubName: string;
  title: string;
  reason: string;
  advisorName: string;
  date: string;
  document: string;
  status: "pending" | "approved" | "rejected";
};

const STATUS_LABEL: Record<string, { label: string; className: string }> = {
  pending: { label: "รอพิจารณา", className: "bg-yellow-100 text-yellow-800" },
  approved: { label: "อนุมัติแล้ว", className: "bg-green-100 text-green-800" },
  rejected: { label: "ไม่อนุมัติ", className: "bg-red-100 text-red-800" },
};

export default function StaffRequestsPage() {
  const router = useRouter();
  const [requests, setRequests] = useState<SpecialRequest[]>([]);
  const [loading, setLoading] = useState(true);
  const [actionLoading, setActionLoading] = useState<string | null>(null);
  const [rejectReason, setRejectReason] = useState<Record<string, string>>({});
  const [showRejectInput, setShowRejectInput] = useState<string | null>(null);

  const fetchRequests = useCallback(async () => {
    try {
      const res = await fetch("/api/staff/requests");
      const data = await res.json();
      if (data.requests) {
        setRequests(data.requests.map((r: any) => ({
          ...r,
          clubName: r.club.name,
          advisorName: r.club.presidentName || "ไม่ระบุ",
          date: new Date(r.createdAt).toLocaleDateString("th-TH"),
          document: "เอกสารแนบ"
        })));
      }
    } catch (err) {
      console.error(err);
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => { fetchRequests(); }, [fetchRequests]);

  const handleAction = async (id: string, status: "approved" | "rejected") => {
    if (status === "rejected" && !rejectReason[id]) return;
    setActionLoading(id);
    try {
      const res = await fetch(`/api/staff/requests/${id}`, {
        method: "PUT",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ status, rejectedReason: rejectReason[id] })
      });
      if (res.ok) {
        setRequests(prev => prev.map(r => r.id === id ? { ...r, status } : r));
        setShowRejectInput(null);
      }
    } catch (err) {
      console.error(err);
    } finally {
      setActionLoading(null);
    }
  };

  const pendingCount = requests.filter((r) => r.status === "pending").length;

  return (
    <div className="min-h-screen bg-gray-50 py-8 px-4">
      <div className="max-w-full lg:max-w-6xl mx-auto">

        <div className="flex items-start justify-between mb-6">
          <div>
            <h1 className="text-2xl font-semibold text-gray-900">คำร้องกรณีพิเศษ</h1>
            <p className="text-gray-500 text-sm mt-1">
              {loading ? "กำลังโหลด..." : `รอพิจารณา ${pendingCount} คำร้อง`}
            </p>
          </div>
          <div className="flex items-center gap-3">
            <button
              onClick={() => router.push("/staff/settings")}
              className="border border-gray-300 hover:bg-gray-50 text-gray-700 text-sm font-medium px-4 py-2 rounded-lg transition-colors cursor-pointer"
            >
              ⚙️ ตั้งค่าระบบ
            </button>
            <LogoutButton />
          </div>
        </div>

        {loading ? (
          <div className="text-center py-16 text-gray-400 text-sm">กำลังโหลด...</div>
        ) : requests.length === 0 ? (
          <div className="text-center py-16 text-gray-400 text-sm">ไม่มีคำร้อง</div>
        ) : (
        <div className="space-y-4">
          {requests.map((r) => (
            <div key={r.id} className="bg-white rounded-xl border border-gray-200 shadow-sm p-5">
              <div className="flex items-center gap-2 mb-2 flex-wrap">
                <h2 className="font-medium text-gray-900">{r.title}</h2>
                <span className={`text-xs px-2 py-0.5 rounded-full font-medium ${STATUS_LABEL[r.status]?.className || "bg-gray-100 text-gray-800"}`}>
                  {STATUS_LABEL[r.status]?.label || r.status}
                </span>
                <span className="text-xs px-2 py-0.5 rounded-full bg-blue-50 text-blue-700">{r.clubName}</span>
              </div>

              <p className="text-sm text-gray-600 mb-3">{r.reason}</p>

              <div className="flex flex-wrap gap-4 text-xs text-gray-500 mb-3">
                <span>👤 อาจารย์ที่ปรึกษา: {r.advisorName}</span>
                <span>📅 {r.date}</span>
              </div>

              <div className="bg-gray-50 rounded-lg px-3 py-2 text-sm text-gray-600 flex items-center gap-2 mb-4">
                <span>📄</span><span>{r.document}</span>
              </div>

              {showRejectInput === r.id && (
                <div className="mb-3">
                  <input
                    className="w-full px-3 py-2 rounded-lg border border-red-200 text-sm focus:outline-none focus:ring-2 focus:ring-red-400"
                    placeholder="ระบุเหตุผลที่ไม่อนุมัติ..."
                    value={rejectReason[r.id] || ""}
                    onChange={(e) => setRejectReason((prev) => ({ ...prev, [r.id]: e.target.value }))}
                  />
                </div>
              )}

              {r.status === "pending" && (
                <div className="flex gap-2">
                  {showRejectInput === r.id ? (
                    <>
                      <button onClick={() => setShowRejectInput(null)} className="flex-1 px-3 py-2 rounded-lg border border-gray-200 text-gray-600 text-sm hover:bg-gray-50 transition-colors cursor-pointer">ยกเลิก</button>
                      <button onClick={() => handleAction(r.id, "rejected")} disabled={!rejectReason[r.id] || actionLoading === r.id} className="flex-1 px-3 py-2 rounded-lg bg-red-600 hover:bg-red-700 disabled:bg-gray-300 text-white text-sm transition-colors cursor-pointer">
                        {actionLoading === r.id ? "กำลังบันทึก..." : "ยืนยันไม่อนุมัติ"}
                      </button>
                    </>
                  ) : (
                    <>
                      <button onClick={() => setShowRejectInput(r.id)} className="flex-1 px-3 py-2 rounded-lg border border-red-200 text-red-600 text-sm hover:bg-red-50 transition-colors cursor-pointer">ไม่อนุมัติ</button>
                      <button onClick={() => handleAction(r.id, "approved")} disabled={actionLoading === r.id} className="flex-1 px-3 py-2 rounded-lg bg-green-600 hover:bg-green-700 disabled:bg-gray-300 text-white text-sm transition-colors cursor-pointer">
                        {actionLoading === r.id ? "กำลังบันทึก..." : "อนุมัติ"}
                      </button>
                    </>
                  )}
                </div>
              )}
            </div>
          ))}
        </div>
        )}
      </div>
    </div>
  );
}

"use client";

import { useState, useEffect } from "react";
import { useRouter } from "next/navigation";
import LogoutButton from "@/components/shared/LogoutButton";

type SportCategory = "mandatory" | "international" | "general" | "thai" | "demonstration" | "";

type Sport = {
  id: string;
  name: string;
  category: SportCategory;
  maxAthletes: number;
  isOpen: boolean;
  positions: string[];
  requirements: string;
  competitionType: "qualifier" | "final_only" | "";
  qualifierNote: string;
  reachedTop16LastYear: boolean | null;
  top16Note: string;
};

const CATEGORY_LABEL: Record<string, { label: string; className: string }> = {
  mandatory: { label: "กีฬาบังคับ", className: "bg-red-100 text-red-700" },
  international: { label: "กีฬาเลือกสากล", className: "bg-blue-100 text-blue-700" },
  general: { label: "กีฬาเลือกทั่วไป", className: "bg-purple-100 text-purple-700" },
  thai: { label: "กีฬาไทย", className: "bg-amber-100 text-amber-700" },
  demonstration: { label: "กีฬาสาธิต", className: "bg-slate-100 text-slate-600" },
};

const CATEGORY_REQUIREMENT: Record<string, string> = {
  mandatory: "ต้องจัดการแข่งขัน (ข้อ 9.1) — 6 ชนิด",
  international: "เลือกจัดอย่างน้อย 17 ชนิด (ข้อ 9.2)",
  general: "เลือกจัดอย่างน้อย 1 ชนิด (ข้อ 9.3)",
  thai: "เลือกจัดอย่างน้อย 1 ชนิด (ข้อ 9.4)",
  demonstration: "ชนิดกีฬาที่ไม่เคยจัดมาก่อน (ข้อ 9.6)",
};

const generateId = () => Math.random().toString(36).substring(2, 9);

type QualifierSchedule = {
  region: string;
  hostUniversity: string;
  startDate: string;
  endDate: string;
  location: string;
  note: string;
};

export default function StaffSettingsPage() {
  const router = useRouter();
  const [sports, setSports] = useState<Sport[]>([]);
  const [editingId, setEditingId] = useState<string | null>(null);
  const [showAddForm, setShowAddForm] = useState(false);
  const [saved, setSaved] = useState(false);
  const [loading, setLoading] = useState(true);

  const [schedule, setSchedule] = useState<QualifierSchedule>({
    region: "", hostUniversity: "", startDate: "", endDate: "", location: "", note: ""
  });
  const [editingSchedule, setEditingSchedule] = useState(false);

  // Import State
  const [importFile, setImportFile] = useState<File | null>(null);
  const [importStatus, setImportStatus] = useState({ loading: false, error: "", success: "" });

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) setImportFile(file);
  };

  const handleImport = async () => {
    if (!importFile) return;
    setImportStatus({ loading: true, error: "", success: "" });
    try {
      const XLSX = await import("xlsx");
      const reader = new FileReader();
      reader.onload = async (e) => {
        try {
          const data = new Uint8Array(e.target?.result as ArrayBuffer);
          const workbook = XLSX.read(data, { type: "array" });
          const firstSheet = workbook.Sheets[workbook.SheetNames[0]];
          const jsonData = XLSX.utils.sheet_to_json(firstSheet);

          const students = jsonData.map((row: any) => {
            // แยกชื่อ-นามสกุล
            const fullName = row["ชื่อ-นามสกุล"] || row["ชื่อ"] || row["First Name"] || row.firstName || "";
            const nameParts = fullName.trim().split(/\s+/);
            const firstName = nameParts[0] || "";
            const lastName = nameParts.slice(1).join(" ") || "";

            // จัดการวันที่ (Excel Date หรือ Text)
            let birthDateStr = "";
            const rawDate = row["วันเดือนปีเกิด"];
            if (rawDate) {
              if (typeof rawDate === "number") {
                // Excel serial date format
                const date = new Date((rawDate - 25569) * 86400 * 1000);
                birthDateStr = date.toISOString();
              } else {
                birthDateStr = String(rawDate);
              }
            }

            // จัดการระดับการศึกษา
            const levelRaw = String(row["ระดับการศึกษา"] || "").toLowerCase();
            const studentLevel = (levelRaw.includes("โท") || levelRaw.includes("เอก") || levelRaw.includes("grad")) ? "GRADUATE" : "BACHELOR";

            // ฟังก์ชันช่วยดึงคีย์ด้วยคำค้นหาบางส่วน
            const findValue = (keyword: string) => {
              const key = Object.keys(row).find(k => k.includes(keyword));
              return key ? row[key] : null;
            };

            const pastCompetitions = [];
            for (let i = 1; i <= 3; i++) {
              const res = findValue(`ผลงานรายการที่ ${i}`);
              if (res) pastCompetitions.push(res);
            }
            const extraRes = findValue("ผลงานเพิ่มเติม");
            if (extraRes) pastCompetitions.push(extraRes);

            const hasParticipated = String(findValue("เคยเข้าร่วมการแข่งขันกีฬามหาวิทยาลัย")).includes("เคย");
            const isNationalTeam = String(findValue("เคยเป็นผู้แทนประเทศไทย")).includes("เคย");

            return {
              studentId: row["รหัสนิสิต"] || row["Student ID"] || row.studentId,
              firstName: firstName,
              lastName: lastName,
              faculty: row["คณะ"] || row.faculty,
              major: row["ภาควิชา"] || row["สาขา"] || row.major,
              nationalId: row["เลขประจำตัวประชาชน"],
              nationality: row["สัญชาติ"],
              birthDate: birthDateStr,
              year: row["ชั้นปี"],
              gpaSemester: row["GPA ภาคการศึกษา"] || row["GPA"],
              gpaCumulative: row["GPAX สะสม"] || row["GPAX"],
              studentLevel: studentLevel,
              // History fields
              hasParticipated: hasParticipated,
              firstSport: findValue("ชนิดกีฬาที่สมัครเข้าร่วมครั้งแรก"),
              participateCountBachelor: findValue("จำนวนครั้งที่เข้าร่วมระดับปริญญาตรี"),
              participateCountMaster: findValue("จำนวนครั้งที่เข้าร่วมระดับปริญญาโท"),
              participateCountPhd: findValue("จำนวนครั้งที่เข้าร่วมระดับปริญญาเอก"),
              lastParticipateYear: findValue("ปี พ.ศ. ที่เข้าร่วมล่าสุด"),
              isNationalTeam: isNationalTeam,
              pastCompetitions: pastCompetitions.length > 0 ? pastCompetitions : null
            };
          }).filter((s: any) => !!s.studentId);

          if (students.length === 0) {
            setImportStatus({ loading: false, error: "ไม่พบข้อมูลรหัสนิสิตในไฟล์", success: "" });
            return;
          }

          const res = await fetch("/api/staff/import", {
            method: "POST",
            headers: { "Content-Type": "application/json" },
            body: JSON.stringify({ students }),
          });
          const result = await res.json();
          if (res.ok) {
            setImportStatus({ loading: false, error: "", success: `นำเข้าสำเร็จ ${result.successCount} คน (ล้มเหลว ${result.errorCount} คน)` });
            setImportFile(null);
          } else {
            setImportStatus({ loading: false, error: result.error || "เกิดข้อผิดพลาดในการนำเข้า", success: "" });
          }
        } catch (err: any) {
          setImportStatus({ loading: false, error: "รูปแบบไฟล์ไม่ถูกต้อง", success: "" });
        }
      };
      reader.readAsArrayBuffer(importFile);
    } catch (err: any) {
      setImportStatus({ loading: false, error: "โหลดไลบรารีไม่สำเร็จ กรุณาลองใหม่", success: "" });
    }
  };

  useEffect(() => {
    fetch("/api/staff/settings")
      .then((res) => res.json())
      .then((data) => {
        if (data.sports) setSports(data.sports);
        if (data.schedule) setSchedule(data.schedule);
        setLoading(false);
      })
      .catch((err) => {
        console.error(err);
        setLoading(false);
      });
  }, []);

  const formatDateRange = (start: string, end: string) => {
    if (!start || !end) return "ยังไม่กำหนด";
    const s = new Date(start);
    const e = new Date(end);
    const thMonths = ["ม.ค.", "ก.พ.", "มี.ค.", "เม.ย.", "พ.ค.", "มิ.ย.", "ก.ค.", "ส.ค.", "ก.ย.", "ต.ค.", "พ.ย.", "ธ.ค."];
    const sBE = s.getFullYear() + 543;
    const eBE = e.getFullYear() + 543;
    if (s.getMonth() === e.getMonth() && sBE === eBE) {
      return `${s.getDate()} - ${e.getDate()} ${thMonths[e.getMonth()]} ${eBE}`;
    }
    return `${s.getDate()} ${thMonths[s.getMonth()]} ${sBE} - ${e.getDate()} ${thMonths[e.getMonth()]} ${eBE}`;
  };

  const [newSport, setNewSport] = useState<Omit<Sport, "id">>({
    name: "",
    category: "",
    maxAthletes: 10,
    isOpen: true,
    positions: [],
    requirements: "",
    competitionType: "",
    qualifierNote: "",
    reachedTop16LastYear: null,
    top16Note: "",
